58	                .build(),
59	        );
60	        let rx = events.subscribe_receiver();
61	        let registry = BlockRegistry::builder().event_manager(events).build();
62	        let pool = Self::build(block_size, num_blocks, registry)?;
63	        Ok((pool, rx))
64	    }
