74	            .block_count(num_blocks)
75	            .block_size(block_size)
76	            .registry(registry)
77	            .duplication_policy(BlockDuplicationPolicy::Allow)
78	            .with_lru_backend()
79	            .build()
80	            .map_err(|e| anyhow::anyhow!("BlockManager build failed: {e}"))?;
81	
82	        // Reserve block 0 as CUDA Graph padding slot.
83	        let padding_blocks = block_manager
