use std::sync::Arc;

use dynamo_kv_hashing::compute_salt_hash;
use kvbm_logical::KvbmSequenceHashProvider;
use kvbm_logical::SequenceHash;
use kvbm_logical::blocks::ImmutableBlock;
use kvbm_logical::blocks::MutableBlock;
use kvbm_logical::events::EventsManager;
use kvbm_logical::events::KvCacheEvent;
use kvbm_logical::integrations::DecodeOutcome;
use kvbm_logical::integrations::SchedulableSequence;
use kvbm_logical::integrations::ScheduleError;
use kvbm_logical::manager::BlockManager;
use kvbm_logical::pools::BlockDuplicationPolicy;
use kvbm_logical::registry::BlockRegistry;
use tokio::sync::broadcast;

use crate::view::KvView;

/// Broadcast capacity for the opt-in KV-event feed. Generous: the scheduler
/// drains it every step, but a step can register/evict many blocks, and a
/// dropped event silently desyncs the router's prefix tree. Only allocated on
/// the [`BlockPool::with_events`] path.
const KV_EVENT_CHANNEL_CAPACITY: usize = 65_536;

/// Logical KV block pool: a `BlockManager` plus the reserved padding block.
///
/// Owns no GPU memory — the physical layout (full-attention `KvBuffer`,
/// MLA dual ckv/kpe buffers, ...) lives with the consumer and is indexed
/// by the block IDs this pool hands out.
pub struct BlockPool {
    block_manager: BlockManager<()>,
    block_size: usize,
    padding_block_id: usize,
}

impl BlockPool {
    pub fn new(block_size: usize, num_blocks: usize) -> anyhow::Result<Self> {
        Self::build(block_size, num_blocks, BlockRegistry::builder().build())
    }

    /// Like [`new`](Self::new), but the pool also emits block store/remove
    /// events for an out-of-band cache-aware router, returned as a raw broadcast
    /// receiver to drain synchronously. The stream carries `Create` events too
    /// (the emission policy can't separate them) — the consumer ignores `Create`
    /// and sources richer store events from the seal site, and maps the lineage
    /// hash in each `Remove` back to the router's `sequence_hash`. OFF by
    /// default: plain single-machine serving uses [`new`](Self::new) and pays
    /// neither the per-block event attachment nor the channel.
    pub(crate) fn with_events(
        block_size: usize,
        num_blocks: usize,
    ) -> anyhow::Result<(Self, broadcast::Receiver<KvCacheEvent>)> {
        // Default emission policy is AllEventsPolicy (every block tracked).
        let events = Arc::new(
            EventsManager::builder()
                .channel_capacity(KV_EVENT_CHANNEL_CAPACITY)
                .build(),
        );
        let rx = events.subscribe_receiver();
        let registry = BlockRegistry::builder().event_manager(events).build();
        let pool = Self::build(block_size, num_blocks, registry)?;
        Ok((pool, rx))
    }

    fn build(
        block_size: usize,
        num_blocks: usize,
        registry: BlockRegistry,
    ) -> anyhow::Result<Self> {
        anyhow::ensure!(num_blocks >= 2, "need at least 2 blocks (1 for padding)");

        let block_manager = BlockManager::builder()
            .block_count(num_blocks)
            .block_size(block_size)
            .registry(registry)
            .duplication_policy(BlockDuplicationPolicy::Allow)
            .with_lru_backend()
            .build()
            .map_err(|e| anyhow::anyhow!("BlockManager build failed: {e}"))?;

        // Reserve block 0 as CUDA Graph padding slot.
        let padding_blocks = block_manager
            .allocate_blocks(1)
            .ok_or_else(|| anyhow::anyhow!("failed to allocate padding block"))?;
        let padding_block_id = padding_blocks[0].block_id();
        let padding_complete = padding_blocks
            .into_iter()
            .next()
            .unwrap()
            .stage(SequenceHash::default(), block_size)
            .map_err(|e| anyhow::anyhow!("padding block stage failed: {e}"))?;
        // Register so it stays alive (ImmutableBlock RAII keeps it out of the
        // free pool), then leak — padding lives for the lifetime of the engine.
        std::mem::forget(block_manager.register_block(padding_complete));

        Ok(Self {
            block_manager,
            block_size,
            padding_block_id,
        })
    }

    pub fn block_size(&self) -> usize {
        self.block_size
    }

    pub fn available_blocks(&self) -> usize {
        self.block_manager.available_blocks()
    }

    pub fn total_blocks(&self) -> usize {
        self.block_manager.total_blocks()
    }

    pub fn padding_block_id(&self) -> i32 {
        self.padding_block_id as i32
    }

    /// Maximum blocks a single request can consume (total minus padding).
    pub fn max_request_blocks(&self) -> usize {
        self.block_manager.total_blocks().saturating_sub(1)
    }

    /// Evict every cached-but-unused block from the GPU prefix cache (drain the
    /// inactive pool). In-use blocks are untouched. A cold-cache flush — and,
    /// for the offload path, the way to force a prefix out of HBM so a
    /// subsequent request must restore it from the CPU tier.
    pub fn evict_inactive(&self) {
        self.block_manager.evict_inactive();

use std::sync::Arc;

use cudarc::driver::CudaStream;
use kvbm_logical::events::KvCacheEvent;
use tokio::sync::broadcast;

use crate::buffer::KvBuffer;
use crate::pool::BlockPool;

/// Engine-level KV cache for full-attention models: one logical
/// [`BlockPool`] + one GPU [`KvBuffer`] with matching geometry.
///
/// MLA models (kimi-k2) consume [`BlockPool`] directly and own their
/// physical buffers — this facade is the full-attention pairing only.
pub struct KvCacheManager {
    pool: BlockPool,
    buffer: KvBuffer,
}

impl KvCacheManager {
    pub fn new(
        stream: &Arc<CudaStream>,
        num_layers: usize,
        num_kv_heads: usize,
        head_dim: usize,
        block_size: usize,
        num_blocks: usize,
    ) -> anyhow::Result<Self> {
        Self::new_with_scratch_pages(
            stream,
            num_layers,
            num_kv_heads,
            head_dim,
            block_size,
            num_blocks,
            0,
        )
    }

    /// Like [`new`](Self::new), plus `scratch_pages` extra pages in the GPU
    /// buffer that the pool never hands out. Their page ids are
    /// `num_blocks..num_blocks + scratch_pages`; ownership and content are the
    /// caller's business (e.g. the speculative hedge's alternative-chain verify
    /// KV). The transaction layer is unaware of them by construction.
    pub fn new_with_scratch_pages(
        stream: &Arc<CudaStream>,
        num_layers: usize,
        num_kv_heads: usize,
        head_dim: usize,
        block_size: usize,
        num_blocks: usize,
        scratch_pages: usize,
    ) -> anyhow::Result<Self> {
        let buffer = KvBuffer::new(
            stream,
            num_layers,
            num_kv_heads,
            head_dim,
            block_size,
            num_blocks.checked_add(scratch_pages).ok_or_else(|| {
                anyhow::anyhow!("KV pages {num_blocks} + scratch {scratch_pages} overflow")
            })?,
        )?;
        let pool = BlockPool::new(block_size, num_blocks)?;
        Ok(Self { pool, buffer })
    }

    /// Pair an existing physical KV buffer with a new logical block pool.
    ///
    /// `num_blocks` may be smaller than the physical allocation. Tensor-parallel
    /// executors use this to choose the minimum common logical capacity across
    /// rank-local buffers while keeping one shared page-id namespace.
    pub fn from_buffer(buffer: KvBuffer, num_blocks: usize) -> anyhow::Result<Self> {
        anyhow::ensure!(
            num_blocks <= buffer.num_blocks(),
            "logical KV block count {num_blocks} exceeds physical buffer capacity {}",
            buffer.num_blocks()
        );
        let pool = BlockPool::new(buffer.layout().page_size, num_blocks)?;
        Ok(Self { pool, buffer })
    }

    /// Like [`new`](Self::new) but the pool emits KV block events; returns the
    /// receiver to drain. See [`BlockPool::with_events`].
    pub fn new_with_events(
        stream: &Arc<CudaStream>,
        num_layers: usize,
        num_kv_heads: usize,
        head_dim: usize,
        block_size: usize,
        num_blocks: usize,
    ) -> anyhow::Result<(Self, broadcast::Receiver<KvCacheEvent>)> {
        let buffer = KvBuffer::new(
            stream,
            num_layers,
            num_kv_heads,
            head_dim,
            block_size,
            num_blocks,
        )?;
        let (pool, events) = BlockPool::with_events(block_size, num_blocks)?;
        Ok((Self { pool, buffer }, events))
    }

    pub fn pool(&self) -> &BlockPool {
        &self.pool
    }

    pub fn buffer(&self) -> &KvBuffer {
        &self.buffer
    }
}

/// Bytes one KV page costs in the pool, for a given page size. The single
/// owner of this formula — callers that bill KV pages (hedge scratch,
/// budgets) must not re-derive it.
pub(crate) fn kv_page_bytes(&self, page_size: usize) -> Result<usize> {
    Self::kv_bytes_per_block(&self.kv_budget_geometry(page_size))
}

fn kv_budget_geometry(&self, page_size: usize) -> KvBudget {
    let num_kv_heads = self.local_num_key_value_heads();
    KvBudget {
        num_layers: self.config.num_hidden_layers,
        num_kv_heads,
        head_dim: self.config.head_dim,
        block_size: page_size,
        num_blocks: 0,
    }
}

fn kv_bytes_per_block(geometry: &KvBudget) -> Result<usize> {
    // Checked BEFORE constructing the layout: `KvLayout::new` derives its
    // strides with plain products, and this full product dominates every
    // partial one, so clearing it clears them all.
    let bytes = crate::sizing::product(&[
        geometry.num_layers,
        2,
        geometry.num_kv_heads,
        geometry.head_dim,
        geometry.block_size,
        std::mem::size_of::<half::bf16>(),
    ])?;
    let layout = pegainfer_kv_cache::KvLayout::new(
        geometry.num_layers,
        geometry.num_kv_heads,
        geometry.head_dim,
        geometry.block_size,
    );
    debug_assert_eq!(
        bytes,
        layout.page_stride * std::mem::size_of::<half::bf16>()
    );
    Ok(bytes)
}

/// Smallest pool the scheduler can make progress with.
const MIN_KV_BLOCKS: usize = 64;

fn kv_budget_from_bytes(
    mut geometry: KvBudget,
    bytes_per_block: usize,
    dflash_kv_bytes_per_token: usize,
    kv_budget_bytes: usize,
    free_bytes: usize,
    source: &'static str,
) -> Result<KvBudget> {
    // DFlash keeps its own per-request KV (plus prompt-scaling scratch) outside
    // the paged pool, scaling with the same token count. Charge it as extra
    // bytes per pool token so the target block count shrinks to leave room; the
    // pool itself is still allocated at the target-only `bytes_per_block`.
    //
    // Checked: the draft config is not shape-validated against the draft
    // weights until the model loads, which is after this budget is fixed.
    let effective_bytes_per_block = crate::sizing::sum(&[
        bytes_per_block,
        crate::sizing::product(&[dflash_kv_bytes_per_token, geometry.block_size])?,
    ])?;
